env:
BASH_FUNC_module%%=() {  if [ -z "${LMOD_SH_DBG_ON+x}" ]; then
 case "$-" in 
 *v*x*)
 __lmod_sh_dbg='vx'
 ;;
 *v*)
 __lmod_sh_dbg='v'
 ;;
 *x*)
 __lmod_sh_dbg='x'
 ;;
 esac;
 fi;
 if [ -n "${__lmod_sh_dbg:-}" ]; then
 set +$__lmod_sh_dbg;
 echo "Shell debugging temporarily silenced: export LMOD_SH_DBG_ON=1 for Lmod's output" 1>&2;
 fi;
 eval "$($LMOD_CMD shell "$@")" && eval "$(${LMOD_SETTARG_CMD:-:} -s sh)";
 __lmod_my_status=$?;
 if [ -n "${__lmod_sh_dbg:-}" ]; then
 echo "Shell debugging restarted" 1>&2;
 set -$__lmod_sh_dbg;
 fi;
 unset __lmod_sh_dbg;
 return $__lmod_my_status
}

BASH_FUNC_jutil%%=() {  if [ $# -gt 1 ] && [ "$1" = "env" ]; then
 if [[ "$@" =~ " -h" || "$@" =~ "--help" ]]; then
 $JUMO_USRCMD_EXEC $@;
 else
 if [[ "$2" = "init" ]]; then
 eval $($JUMO_USRCMD_EXEC $@);
 else
 jres=$($JUMO_USRCMD_EXEC $@);
 jrc=$?;
 if [ $jrc -eq 0 ]; then
 eval "$jres";
 else
 return $jrc;
 fi;
 fi;
 fi;
 else
 $JUMO_USRCMD_EXEC $@;
 fi
}
